import importlib.util
import pathlib
import sys
repo = pathlib.Path(sys.argv[1]).resolve()
spec = importlib.util.spec_from_file_location("candidate_solution", repo / "solution.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
def raises(kind, fn, *args):
    try:
        fn(*args)
    except kind:
        return
    raise AssertionError("Expected " + kind.__name__)
a = {"x": "", "z": 0, "f": False, "n": None}
assert m.lookup(a, "x") == ""
assert m.lookup(a, "z") == 0
assert m.lookup(a, "f") is False
assert m.lookup(a, "n") is None
assert m.lookup(a, "absent") == "MISSING"
assert a == {"x": "", "z": 0, "f": False, "n": None}

